head.script:
scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
      // 기존 target 있으면 삭제
    if (typeof startcomp !== 'undefined') {
        startcomp.remove();
    }

    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    if (typeof selectbox2 !== 'undefined') {
        selectbox2.remove();
    }

    if (typeof autocomplete2 !== 'undefined') {
        autocomplete2.remove();
    }    

    if (typeof input2 !== 'undefined') {
        input2.remove();
    }   

    $c.gcm.createBasicInput('tabIndex="1"', '', 'startcomp');  
    $c.gcm.createBasicInputCalendar('tabIndex="2"', 'ev:onfocus="scwin.target1_onfocus"', 'target1');
    $c.gcm.createBasicSelectBox('tabIndex="3"', 'ev:onfocus="scwin.selectbox2_onfocus"', 'selectbox2');
    $c.gcm.createBasicAutoComplete('tabIndex="4"', 'ev:onfocus="scwin.autocomplete2_onfocus"', 'autocomplete2');
    $c.gcm.createBasicInput('tabIndex="5"', 'ev:onfocus="scwin.input2_onfocus"', 'input2');

    startcomp.setValue("start");
    // target1.setValue("target1");
    input2.setValue("input2");
}
